package vn.covie.cart.application;
import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.covie.auth.security.CurrentActorProvider; import vn.covie.cart.api.dto.*; import vn.covie.cart.model.*; import vn.covie.cart.persistence.*; import vn.covie.shared.concurrency.VersionPrecondition; import vn.covie.shared.time.AppClock; import vn.covie.shared.web.*;
@Service public class CartMutationService{private final CurrentActorProvider actors;private final CartRepository carts;private final CartItemRepository items;private final AppClock clock;private final CartService views;public CartMutationService(CurrentActorProvider actors,CartRepository carts,CartItemRepository items,AppClock clock,CartService views){this.actors=actors;this.carts=carts;this.items=items;this.clock=clock;this.views=views;}@Transactional public CartResponse update(UUID cartId,UUID itemId,String ifMatch,UpdateCartItemRequest req){CartEntity c=lock(cartId,ifMatch);CartItemEntity i=items.findById(itemId).filter(x->x.getCartId().equals(cartId)).orElseThrow(CartMutationService::notFound);if(req==null||req.quantity()<1||(c.getCartType()==CartType.SERVICE&&req.quantity()!=1))throw invalid("Invalid quantity.");i.setQuantity(req.quantity(),clock.now());items.save(i);c.touch(clock.now());carts.saveAndFlush(c);return views.get(cartId);}@Transactional public void remove(UUID cartId,UUID itemId,String ifMatch){CartEntity c=lock(cartId,ifMatch);CartItemEntity i=items.findById(itemId).filter(x->x.getCartId().equals(cartId)).orElseThrow(CartMutationService::notFound);items.delete(i);if(items.findByCartIdOrderByAddedAtAsc(cartId).isEmpty())c.abandon(clock.now());else c.touch(clock.now());carts.save(c);}private CartEntity lock(UUID id,String ifMatch){UUID user=actors.currentActor().userId();CartEntity c=carts.findActiveByIdAndUserIdForUpdate(id,user).orElseThrow(CartMutationService::notFound);VersionPrecondition.require(VersionPrecondition.parseRequired(ifMatch),c.getVersion());return c;}private static ApiException invalid(String m){return new ApiException(ErrorCode.CART_ITEM_INVALID,HttpStatus.UNPROCESSABLE_ENTITY,m);}private static ApiException notFound(){return new ApiException(ErrorCode.RESOURCE_NOT_FOUND,HttpStatus.NOT_FOUND,"Resource not found.");}}
